if (!valid) { msg.statusCode=403; msg.payload={error:'forbidden'}; msg.headers = { 'Access-Control-Allow-Origin': '*','Content-Type':'application/json','Cache-Control':'no-store'}; return msg; }
const fs = global.get('fs');
const dir = '/data/electric-log';
const out = { pending: null, session: null, last: null, count: 0 };
try { out.pending = JSON.parse(fs.readFileSync(dir + '/pending_swap.json', 'utf8')); } catch (e) {}
try { out.session = JSON.parse(fs.readFileSync(dir + '/charging_session.json', 'utf8')); } catch (e) {}
try {
  const lines = fs.readFileSync(dir + '/records.jsonl', 'utf8').split('\n').filter(Boolean);
  out.count = lines.length;
  if (lines.length) {
    try { out.last = JSON.parse(lines[lines.length - 1]); } catch (e) {}
  }
} catch (e) {}
const tmpSoc = flow.get('curSoc', 'file');
out.soc = tmpSoc != null && tmpSoc !== '' ? Number(tmpSoc) : null;
out.mileage = flow.get('curMile', 'file') != null && flow.get('curMile', 'file') !== '' ? Number(flow.get('curMile', 'file')) : null;
/* 续航估算：容量×SOC÷平均墙端电耗（由集成侧统一计算） */
let range = null;
if (out.soc != null) {
  try {
    const fsx = global.get('fs');
    const lines = fsx.readFileSync('/data/electric-log/records.jsonl', 'utf8').split('\n').filter(Boolean);
    let totalKwh = 0;
    const mileSet = [];
    lines.forEach(function (l) {
      try {
        const r = JSON.parse(l);
        if (r.energyKwh != null) totalKwh += Number(r.energyKwh);
        if (r.mileage != null) mileSet.push(Number(r.mileage));
      } catch (e) {}
    });
    let totalKm = 0;
    if (mileSet.length >= 2) totalKm = Math.max.apply(null, mileSet) - Math.min.apply(null, mileSet);
    const wallWhKm = totalKm > 0 && totalKwh > 0 ? totalKwh * 1000 / totalKm : null;
    if (wallWhKm) range = Math.round(1863 * out.soc / 100 / wallWhKm);
  } catch (e) {}
}
out.range = range;
msg.payload = out;
msg.headers = { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json', 'Cache-Control': 'no-store' };
return msg;

const fs = global.get('fs');
